fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len() as u8; // Get the length of the original vector

    // If the original length is greater than or equal to the target width, return it unchanged
    if orig_len >= width {
        return orig;
    }

    // Calculate the number of fill characters needed
    let fill_count = width - orig_len;

    // Create a new vector with the required width
    let mut res = Vec::with_capacity(width as usize);

    // Fill the leading positions with the fill character
    for _ in 0..fill_count {
        res.push(fillchar);
    }

    // Append the original characters
    res.extend(orig);

    res
}